def is_inertial(arr):
    odd_val, even_val = [], []
    max_val = max(arr)

    for i in range(len(arr)):
        if arr[i] % 2 != 0:
            odd_val.append(arr[i])
        else:
            even_val.append(arr[i])

    if max_val % 2 != 0:
        return False

    for i in range(len(odd_val)):
        if odd_val[i] < max_val:
            return False

    return len(odd_val) > 0 and len(even_val) > 0
